CREATE TABLE `corp_portal`.`b_tasks` (`ID` Int64, `TITLE` Nullable(String), `DESCRIPTION` Nullable(String), `DESCRIPTION_IN_BBCODE` Bool, `PRIORITY` UInt8, `STATUS` UInt8, `RESPONSIBLE_ID` Nullable(UInt32), `DATE_START` Nullable(DateTime), `DURATION_PLAN` Nullable(UInt32), `DURATION_FACT` Nullable(UInt32), `DURATION_TYPE` LowCardinality(String), `REPLICATE` Bool, `DEADLINE` Nullable(DateTime), `START_DATE_PLAN` Nullable(DateTime), `END_DATE_PLAN` Nullable(DateTime), `CREATED_BY` Nullable(UInt32), `CREATED_DATE` DateTime, `CHANGED_BY` Nullable(UInt32), `CHANGED_DATE` DateTime, `STATUS_CHANGED_BY` Nullable(UInt32), `STATUS_CHANGED_DATE` Nullable(DateTime), `CLOSED_BY` Nullable(UInt32), `CLOSED_DATE` Nullable(DateTime), `ACTIVITY_DATE` Nullable(DateTime), `XML_ID` Nullable(String), `EXCHANGE_ID` Nullable(String), `EXCHANGE_MODIFIED` Nullable(String), `OUTLOOK_VERSION` Nullable(String), `MARK` LowCardinality(Nullable(FixedString(1))), `ALLOW_CHANGE_DEADLINE` Bool, `TASK_CONTROL` Bool, `ADD_IN_REPORT` Bool, `GROUP_ID` Nullable(UInt32), `PARENT_ID` Nullable(UInt32), `FORUM_TOPIC_ID` Nullable(UInt32), `MULTITASK` Bool, `SITE_ID` LowCardinality(String), `DECLINE_REASON` Nullable(String), `GUID` String, `FORKED_BY_TEMPLATE_ID` Nullable(UInt32), `ZOMBIE` Bool, `DEADLINE_COUNTED` Int32, `TIME_ESTIMATE` Int32, `ALLOW_TIME_TRACKING` Bool, `MATCH_WORK_TIME` Bool, `STAGE_ID` Nullable(UInt32), `IS_REGULAR` Bool) ENGINE = ReplicatedReplacingMergeTree(CHANGED_DATE) PARTITION BY toYear(CREATED_DATE) ORDER BY (ID, GUID) SETTINGS index_granularity = 8192;

CREATE TABLE `corp_portal`.`b_tasks_elapsed_time` (`ID` UInt64, `CREATED_DATE` DateTime, `USER_ID` UInt32, `TASK_ID` UInt32, `MINUTES` Int32, `COMMENT_TEXT` String, `SECONDS` UInt32, `SOURCE` UInt32, `DATE_START` Nullable(DateTime), `DATE_STOP` Nullable(DateTime)) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYear(CREATED_DATE) ORDER BY (TASK_ID, USER_ID, ID) SETTINGS index_granularity = 8192;

CREATE TABLE `corp_portal`.`b_tasks_log` (`CREATED_DATE` DateTime, `USER_ID` UInt32, `TASK_ID` UInt32, `FIELD` LowCardinality(String), `FROM_VALUE` String, `TO_VALUE` String, `ID` UInt32) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYear(CREATED_DATE) ORDER BY (toDate(CREATED_DATE), TASK_ID, ID) SETTINGS index_granularity = 8192;

