CREATE TABLE `corp_portal`.`employees` (`Сотрудник` String, `Организация` String, `Тип услуг` Nullable(String), `Направление` Nullable(String), `Ответсвенный за работы` Nullable(String), `Ответсвенный за бюджет` Nullable(String), `Источник` Nullable(String), `Пропускаем` Nullable(String), `timestamp` DateTime, `UserId` String) ENGINE = ReplicatedReplacingMergeTree() ORDER BY (`Сотрудник`, `Организация`) SETTINGS index_granularity = 8192;

